  function rays(cx,cy,r1,r2,n,off){var s='',i,a;off=off||0;for(i=0;i<n;i++){a=(i*360/n+off)*Math.PI/180;s+=P('M'+(cx+Math.cos(a)*r1).toFixed(1)+' '+(cy+Math.sin(a)*r1).toFixed(1)+'L'+(cx+Math.cos(a)*r2).toFixed(1)+' '+(cy+Math.sin(a)*r2).toFixed(1));}return s;}
  function hatch(x,y,w,h,gap,slant){var s='',i;slant=slant||0;for(i=0;i<=w;i+=gap)s+=P('M'+(x+i)+' '+y+'L'+(x+i+slant)+' '+(y+h));return s;}
  function teeth(x,y,w,step,up){var s=P('M'+x+' '+y+'L'+(x+w)+' '+y)+P('M'+x+' '+(y+(up?5:-5))+'L'+(x+w)+' '+(y+(up?5:-5))),i;for(i=0;i<w;i+=step){s+=P('M'+(x+i)+' '+y+'L'+(x+i+step/2)+' '+(y+(up?-step*.75:step*.75))+'L'+(x+i+step)+' '+y);s+=P('M'+(x+i+step*.28)+' '+y+'L'+(x+i+step/2)+' '+(y+(up?-step*.42:step*.42))+'L'+(x+i+step*.72)+' '+y);}return s;}
