  function EL(x,y,rx,ry,rot){return '<ellipse cx="'+(+x).toFixed(1)+'" cy="'+(+y).toFixed(1)+'" rx="'+(+rx).toFixed(1)+'" ry="'+(+ry).toFixed(1)+'"'+(rot?' transform="rotate('+(+rot).toFixed(1)+' '+(+x).toFixed(1)+' '+(+y).toFixed(1)+')"':'')+'/>';}
  function rays(cx,cy,r1,r2,n,off){var s='',i,a;off=off||0;for(i=0;i<n;i++){a=(i*360/n+off)*Math.PI/180;s+=P('M'+(cx+Math.cos(a)*r1).toFixed(1)+' '+(cy+Math.sin(a)*r1).toFixed(1)+'L'+(cx+Math.cos(a)*r2).toFixed(1)+' '+(cy+Math.sin(a)*r2).toFixed(1));}return s;}
