  function diamondBand(x,y,w,h,step){var s=P('M'+x+' '+y+'L'+(x+w)+' '+y)+P('M'+x+' '+(y+h)+'L'+(x+w)+' '+(y+h)),i,cy=y+h/2;for(i=0;i<w;i+=step){var mx=x+i+step/2;s+=P('M'+(x+i)+' '+cy+'L'+mx+' '+(y+2)+'L'+(x+i+step)+' '+cy+'L'+mx+' '+(y+h-2)+'Z');s+=C(mx,cy,2.6);}return s;}
  function scallop(x,y,w,step,down){var s='',i,dir=down?1:-1;for(i=0;i<w;i+=step){s+=P('M'+(x+i)+' '+y+' Q '+(x+i+step/2)+' '+(y+dir*step*.72)+' '+(x+i+step)+' '+y);}return s;}
  function lotus(cx,cy,r,n){var s='',i;for(i=0;i<n;i++){var rot=i*360/n;s+='<path d="M'+cx+' '+cy+' Q '+(cx-r*.34)+' '+(cy-r*.62)+' '+cx+' '+(cy-r)+' Q '+(cx+r*.34)+' '+(cy-r*.62)+' '+cx+' '+cy+'Z" transform="rotate('+rot+' '+cx+' '+cy+')"/>';}return s+C(cx,cy,r*.2)+C(cx,cy,r*.08);}
  function mandala(cx,cy,r){return{m:C(cx,cy,r)+C(cx,cy,r*.82)+C(cx,cy,r*.5)+rays(cx,cy,r*.5,r*.82,24),a:lotus(cx,cy,r*.48,12)+rays(cx,cy,r*.82,r,36,5)};}
  function fish(x,y,k,flip){var g='<g transform="translate('+x+' '+y+') scale('+(flip?-k:k)+' '+k+')">';g+=P('M0 0 C 18 -22 54 -22 74 0 C 54 22 18 22 0 0Z')+P('M74 0 L 95 -16 Q 88 0 95 16 Z')+C(21,-4,3)+P('M30 -14 L 30 14 M40 -16 L 40 16 M50 -15 L 50 15 M60 -11 L 60 11');return g+'</g>';}
