  function antibody(cx,cy,k,rot){var g='<g transform="translate('+cx+' '+cy+') rotate('+(rot||0)+') scale('+k+')">';g+=P('M-4 36 L -4 4 L -26 -24 M4 36 L 4 4 L 26 -24 M-10 -2 L -28 -20 M10 -2 L 28 -20')+C(-26,-24,4)+C(26,-24,4)+C(0,36,3.5);return g+'</g>';}
  function helix(cx,y1,y2,amp){var m='',a='',y,step=26;for(y=y1;y<y2;y+=step){var ph=(y-y1)/44,x1=cx+Math.sin(ph)*amp,x2=cx-Math.sin(ph)*amp;var ph2=(y+step-y1)/44,nx1=cx+Math.sin(ph2)*amp,nx2=cx-Math.sin(ph2)*amp;m+=P('M'+x1.toFixed(1)+' '+y+' L '+nx1.toFixed(1)+' '+(y+step));a+=P('M'+x2.toFixed(1)+' '+y+' L '+nx2.toFixed(1)+' '+(y+step));if(Math.abs(x1-x2)>10)m+=P('M'+x1.toFixed(1)+' '+y+' L '+x2.toFixed(1)+' '+y);}return{m:m,a:a};}
  function ziggurat(cx,by,w){var m='',a='';m+=P('M'+(cx-w/2)+' '+by+' L '+(cx+w/2)+' '+by+' L '+(cx+w/2)+' '+(by-52)+' L '+(cx-w/2)+' '+(by-52)+'Z');m+=P('M'+(cx-w*.36)+' '+(by-52)+' L '+(cx+w*.36)+' '+(by-52)+' L '+(cx+w*.36)+' '+(by-98)+' L '+(cx-w*.36)+' '+(by-98)+'Z');m+=P('M'+(cx-w*.22)+' '+(by-98)+' L '+(cx+w*.22)+' '+(by-98)+' L '+(cx+w*.22)+' '+(by-138)+' L '+(cx-w*.22)+' '+(by-138)+'Z');a+=P('M'+(cx-16)+' '+by+' L '+(cx-10)+' '+(by-138)+' M'+(cx+16)+' '+by+' L '+(cx+10)+' '+(by-138))+hatch(cx-w/2+10,by-44,w-20,36,22,0);return{m:m,a:a};}
  function cuneiformBand(x,y,w,step){var s=P('M'+x+' '+y+'L'+(x+w)+' '+y)+P('M'+x+' '+(y+18)+'L'+(x+w)+' '+(y+18)),i;for(i=0;i<w;i+=step){s+=P('M'+(x+i+4)+' '+(y+4)+' L '+(x+i+14)+' '+(y+9)+' L '+(x+i+4)+' '+(y+14)+' Z M'+(x+i+14)+' '+(y+9)+' L '+(x+i+step-4)+' '+(y+9));}return s;}

